node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get all SFO->LAS flights
const leg1s = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, dates_json FROM flights WHERE source_skill='tau2Airline' AND origin='SFO' AND destination='LAS'\").all();
// Get all LAS->LAX flights
const leg2s = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, dates_json FROM flights WHERE source_skill='tau2Airline' AND origin='LAS' AND destination='LAX'\").all();

const results = [];

for (const f1 of leg1s) {
  const dates1 = JSON.parse(f1.dates_json || '{}');
  for (const f2 of leg2s) {
    const dates2 = JSON.parse(f2.dates_json || '{}');
    // Find common available dates
    for (const [date, info1] of Object.entries(dates1)) {
      if (info1.status !== 'available') continue;
      // Check same date or next day for connecting flight
      const info2 = dates2[date];
      if (info2 && info2.status === 'available') {
        // Leg 2 must depart after leg 1 arrives
        if (f2.departure_time >= f1.arrival_time) {
          const layover_h = parseInt(f2.departure_time.split(':')[0]) - parseInt(f1.arrival_time.split(':')[0]);
          const layover_m = parseInt(f2.departure_time.split(':')[1]) - parseInt(f1.arrival_time.split(':')[1]);
          const layover_mins = layover_h * 60 + layover_m;
          results.push({
            date,
            leg1_flight: f1.flight_id,
            leg1_route: f1.origin + ' -> ' + f1.destination,
            leg1_dep: f1.departure_time,
            leg1_arr: f1.arrival_time,
            leg1_business_price: info1.prices.business,
            leg1_business_seats: info1.available_seats.business,
            leg2_flight: f2.flight_id,
            leg2_route: f2.origin + ' -> ' + f2.destination,
            leg2_dep: f2.departure_time,
            leg2_arr: f2.arrival_time,
            leg2_business_price: info2.prices.business,
            leg2_business_seats: info2.available_seats.business,
            layover_minutes: layover_mins,
            total_business_price: info1.prices.business + info2.prices.business,
          });
        }
      }
    }
  }
}

results.sort((a,b) => a.date.localeCompare(b.date) || a.total_business_price - b.total_business_price);
console.log(JSON.stringify(results, null, 2));
console.log('\\nTotal options found:', results.length);
"
